-- Uploaded specular microscopy images and the analyses run on them.
-- Image bytes live in a private Supabase Storage bucket; only the object
-- reference is stored here. Paths are generated by the server, never by clients.

CREATE TABLE analysis_images (
    id            UUID                     PRIMARY KEY,
    case_id       VARCHAR(100)             NOT NULL,
    bucket        VARCHAR(100)             NOT NULL,
    object_path   VARCHAR(300)             NOT NULL,
    content_type  VARCHAR(50)              NOT NULL,
    size_bytes    BIGINT                   NOT NULL,
    sha256        VARCHAR(64)              NOT NULL,
    width         INTEGER                  NOT NULL,
    height        INTEGER                  NOT NULL,
    uploaded_by   BIGINT                   NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uk_analysis_images_object UNIQUE (bucket, object_path),
    CONSTRAINT fk_analysis_images_user FOREIGN KEY (uploaded_by) REFERENCES app_users (id)
);

CREATE INDEX idx_analysis_images_case_id ON analysis_images (case_id);
CREATE INDEX idx_analysis_images_uploaded_by ON analysis_images (uploaded_by);

CREATE TABLE analysis_runs (
    id             UUID                     PRIMARY KEY,
    image_id       UUID                     NOT NULL,
    case_id        VARCHAR(100)             NOT NULL,
    requested_by   BIGINT                   NOT NULL,
    ecd            DOUBLE PRECISION,
    status         VARCHAR(20)              NOT NULL,
    error_code     VARCHAR(50),
    result_json    TEXT,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_analysis_runs_image FOREIGN KEY (image_id) REFERENCES analysis_images (id),
    CONSTRAINT fk_analysis_runs_user FOREIGN KEY (requested_by) REFERENCES app_users (id)
);

CREATE INDEX idx_analysis_runs_image_id ON analysis_runs (image_id);
CREATE INDEX idx_analysis_runs_case_id ON analysis_runs (case_id);
